package com.github.uscexp.jfilework.core.config;

import java.util.List;
import java.util.Map;

/**
 * Declarative binding between UI element and command invocation.
 */
public record ActionConfig(
        String id,
        String label,
        String commandId,
        Map<String, String> params,
        String shortcut,
        List<String> placement
) {
}

package com.github.uscexp.jfilework.core.config;

/**
 * Backward-compatible alias type for action-based command bindings.
 */
public record CommandBindingConfig(ActionConfig action) {
}

package com.github.uscexp.jfilework.core.config;

/**
 * UI related user configuration.
 */
public record UiConfig(
        String theme,
        boolean showHiddenFiles,
        String leftStartPath,
        String rightStartPath
) {

    public static UiConfig defaults() {
        return new UiConfig("system", false, null, null);
    }
}

package com.github.uscexp.jfilework.ui.javafx.action;

import java.util.Map;

/**
 * UI callback for executing a command resolved from configuration.
 */
@FunctionalInterface
public interface CommandExecutionHandler {

    void execute(String commandId, Map<String, String> params, String actionLabel);
}

package com.github.uscexp.jfilework.ui.javafx.action;

import java.util.List;
import java.util.Map;

/**
 * Runtime action model generated from configuration.
 */
public record ConfiguredAction(
        String id,
        String label,
        String commandId,
        Map<String, String> params,
        String shortcut,
        List<String> placement,
        boolean enabled
) {
}

package com.github.uscexp.jfilework.ui.javafx.action;

import javafx.scene.Scene;
import javafx.scene.input.KeyCombination;
import javafx.scene.input.KeyEvent;

import java.util.List;

/**
 * Registers and dispatches configured key bindings.
 */
public class KeyBindingService {

    public void bind(Scene scene, List<ConfiguredAction> actions, CommandExecutionHandler handler) {
        scene.addEventFilter(KeyEvent.KEY_PRESSED, event -> {
            for (ConfiguredAction action : actions) {
                if (!action.enabled() || action.shortcut() == null || action.shortcut().isBlank()) {
                    continue;
                }
                KeyCombination keyCombination;
                try {
                    keyCombination = KeyCombination.keyCombination(action.shortcut());
                } catch (IllegalArgumentException ignored) {
                    continue;
                }
                if (keyCombination.match(event)) {
                    handler.execute(action.commandId(), action.params(), action.label());
                    event.consume();
                    break;
                }
            }
        });
    }
}

package com.github.uscexp.jfilework.ui.javafx.action;

import javafx.scene.control.Menu;
import javafx.scene.control.MenuItem;
import javafx.scene.control.SeparatorMenuItem;

import java.util.List;

/**
 * Builds menu entries from configured actions.
 */
public class MenuBuilder {

    public void build(Menu fileMenu, Menu toolsMenu, List<ConfiguredAction> actions, CommandExecutionHandler handler) {
        removeDynamicItems(fileMenu);
        removeDynamicItems(toolsMenu);

        addItems(fileMenu, actions, "menu.file", handler);
        addItems(toolsMenu, actions, "menu.tools", handler);
    }

    private void addItems(Menu menu, List<ConfiguredAction> actions, String placement, CommandExecutionHandler handler) {
        boolean hasStaticItems = !menu.getItems().isEmpty();
        int inserted = 0;

        for (ConfiguredAction action : actions) {
            if (!action.placement().contains(placement)) {
                continue;
            }

            MenuItem item = new MenuItem(action.label());
            item.setId("action-" + action.id());
            item.getProperties().put("dynamicAction", Boolean.TRUE);
            item.setDisable(!action.enabled());
            item.setOnAction(event -> handler.execute(action.commandId(), action.params(), action.label()));
            menu.getItems().add(0, item);
            inserted++;
        }

        if (hasStaticItems && inserted > 0 && !menu.getItems().isEmpty()) {
            boolean alreadySeparated = menu.getItems().stream().findFirst().orElse(null) instanceof SeparatorMenuItem;
            if (!alreadySeparated) {
                SeparatorMenuItem separator = new SeparatorMenuItem();
                separator.getProperties().put("dynamicAction", Boolean.TRUE);
                menu.getItems().add(inserted, separator);
            }
        }
    }

    private static void removeDynamicItems(Menu menu) {
        menu.getItems().removeIf(item -> Boolean.TRUE.equals(item.getProperties().get("dynamicAction")));
    }
}

package com.github.uscexp.jfilework.ui.javafx.action;

import com.github.uscexp.jfilework.core.command.CommandContext;

import java.nio.file.Path;
import java.util.HashMap;
import java.util.Map;
import java.util.stream.Collectors;

/**
 * Resolves simple placeholders used by command parameter templates.
 */
public class ParamTemplateEngine {

    public Map<String, String> resolve(Map<String, String> templateParams, CommandContext context) {
        Map<String, String> resolved = new HashMap<>();
        if (templateParams == null) {
            return resolved;
        }

        for (Map.Entry<String, String> entry : templateParams.entrySet()) {
            resolved.put(entry.getKey(), resolveValue(entry.getValue(), context));
        }
        return resolved;
    }

    private String resolveValue(String value, CommandContext context) {
        if (value == null) {
            return "";
        }

        String result = value;
        result = result.replace("${activePane.path}", context.activeDirectory().toString());
        result = result.replace("${inactivePane.path}", context.inactiveDirectory().toString());
        result = result.replace("${selection.paths}", context.selection().paths().stream()
                .map(Path::toString)
                .collect(Collectors.joining(" ")));
        return result;
    }
}

package com.github.uscexp.jfilework.ui.javafx.action;

import javafx.scene.control.Button;
import javafx.scene.control.ToolBar;

import java.util.List;

/**
 * Builds toolbar buttons from configured actions.
 */
public class ToolbarBuilder {

    public void build(ToolBar toolBar, List<ConfiguredAction> actions, CommandExecutionHandler handler) {
        toolBar.getItems().clear();

        actions.stream()
                .filter(action -> action.placement().contains("toolbar.main"))
                .forEach(action -> {
                    Button button = new Button(action.label());
                    button.setId("action-" + action.id());
                    button.setDisable(!action.enabled());
                    button.setOnAction(event -> handler.execute(action.commandId(), action.params(), action.label()));
                    toolBar.getItems().add(button);
                });
    }
}

package com.github.uscexp.jfilework.ui.javafx.action;

import com.github.uscexp.jfilework.core.command.CommandRegistry;
import com.github.uscexp.jfilework.core.config.ActionConfig;
import com.github.uscexp.jfilework.core.config.AppConfig;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.List;
import java.util.Map;

/**
 * Converts configuration entries into runtime actions and marks unknown commands as disabled.
 */
public class UiActionMapper {

    private static final Logger log = LoggerFactory.getLogger(UiActionMapper.class);

    private final CommandRegistry commandRegistry;

    public UiActionMapper(CommandRegistry commandRegistry) {
        this.commandRegistry = commandRegistry;
    }

    public List<ConfiguredAction> map(AppConfig appConfig) {
        if (appConfig == null || appConfig.actions() == null) {
            return List.of();
        }

        return appConfig.actions().stream()
                .map(this::mapAction)
                .toList();
    }

    private ConfiguredAction mapAction(ActionConfig actionConfig) {
        boolean available = commandRegistry.findById(actionConfig.commandId()).isPresent();
        if (!available) {
            log.warn("Action '{}' references unknown command '{}'", actionConfig.id(), actionConfig.commandId());
        }

        return new ConfiguredAction(
                actionConfig.id(),
                actionConfig.label(),
                actionConfig.commandId(),
                actionConfig.params() == null ? Map.of() : actionConfig.params(),
                actionConfig.shortcut() == null ? "" : actionConfig.shortcut(),
                actionConfig.placement() == null ? List.of() : actionConfig.placement(),
                available
        );
    }
}

package com.github.uscexp.jfilework.ui.javafx;

import javafx.scene.control.Button;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;

import java.nio.file.Path;

import static org.junit.jupiter.api.Assertions.assertTrue;

@Tag("ui")
class DisabledActionUiTest extends MainWindowUiTestBase {

    @BeforeAll
    static void useInvalidCommandConfig() throws Exception {
        String config = """
                {
                  "ui": { "theme": "system", "showHiddenFiles": false, "leftStartPath": "", "rightStartPath": "" },
                  "actions": [
                    {
                      "id": "brokenAction",
                      "label": "Broken Action",
                      "commandId": "missing.command",
                      "params": {},
                      "shortcut": "",
                      "placement": ["toolbar.main"]
                    }
                  ]
                }
                """;
        Path configPath = writeConfigFile("jfilework-m3-disabled", config);
        System.setProperty("jfilework.config", configPath.toString());
    }

    @Test
    void unknownCommandActionIsDisabledInToolbar() {
        Button button = lookup("#action-brokenAction").queryAs(Button.class);
        assertTrue(button.isDisable(), "Expected toolbar action to be disabled for unknown command");
    }
}

package com.github.uscexp.jfilework.ui.javafx;

import com.github.uscexp.jfilework.ui.javafx.model.FileItemViewModel;
import javafx.scene.control.TableView;
import javafx.scene.input.KeyCode;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;
import org.testfx.util.WaitForAsyncUtils;

import java.nio.file.Path;
import java.util.concurrent.TimeUnit;

import static org.junit.jupiter.api.Assertions.assertTrue;

@Tag("ui")
class HotkeyBindingUiTest extends MainWindowUiTestBase {

    @BeforeAll
    static void useHotkeyConfig() throws Exception {
        String config = """
                {
                  "ui": { "theme": "system", "showHiddenFiles": false, "leftStartPath": "", "rightStartPath": "" },
                  "actions": [
                    {
                      "id": "copyByF9",
                      "label": "Copy with F9",
                      "commandId": "file.copy",
                      "params": { "target": "${inactivePane.path}" },
                      "shortcut": "F9",
                      "placement": ["menu.tools"]
                    }
                  ]
                }
                """;
        Path configPath = writeConfigFile("jfilework-m3-hotkey", config);
        System.setProperty("jfilework.config", configPath.toString());
    }

    @Test
    void configuredHotkeyTriggersCommandWithoutMouse() {
        clickOn("#leftFileTable");
        clickOn("alpha.txt");
        push(KeyCode.F9);

        WaitForAsyncUtils.sleep(500, TimeUnit.MILLISECONDS);

        TableView<FileItemViewModel> rightTable = lookup("#rightFileTable").queryTableView();
        boolean containsCopiedFile = rightTable.getItems().stream()
                .anyMatch(item -> "alpha.txt".equals(item.getName()));
        assertTrue(containsCopiedFile, "Expected alpha.txt copied via configured F9 hotkey");
    }
}

package com.github.uscexp.jfilework.ui.javafx;

import com.github.uscexp.jfilework.ui.javafx.model.FileItemViewModel;
import javafx.scene.control.TableView;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;
import org.testfx.util.WaitForAsyncUtils;

import java.nio.file.Path;
import java.util.concurrent.TimeUnit;

import static org.junit.jupiter.api.Assertions.assertTrue;

@Tag("ui")
class ToolbarConfigUiTest extends MainWindowUiTestBase {

    @BeforeAll
    static void useToolbarConfig() throws Exception {
        String config = """
                {
                  "ui": { "theme": "system", "showHiddenFiles": false, "leftStartPath": "", "rightStartPath": "" },
                  "actions": [
                    {
                      "id": "copyBtn",
                      "label": "Copy via Toolbar",
                      "commandId": "file.copy",
                      "params": { "target": "${inactivePane.path}" },
                      "shortcut": "",
                      "placement": ["toolbar.main"]
                    }
                  ]
                }
                """;
        Path configPath = writeConfigFile("jfilework-m3-toolbar", config);
        System.setProperty("jfilework.config", configPath.toString());
    }

    @Test
    void toolbarButtonFromConfigExecutesCommand() {
        clickOn("#leftFileTable");
        clickOn("alpha.txt");
        clickOn("#action-copyBtn");

        WaitForAsyncUtils.sleep(500, TimeUnit.MILLISECONDS);

        TableView<FileItemViewModel> rightTable = lookup("#rightFileTable").queryTableView();
        boolean containsCopiedFile = rightTable.getItems().stream()
                .anyMatch(item -> "alpha.txt".equals(item.getName()));
        assertTrue(containsCopiedFile, "Expected alpha.txt copied via configured toolbar button");
    }
}
